const fs = require('fs');
const NL = String.fromCharCode(10);
const r = $json || {};
const vp = r.vault_path;
if (!vp || !r.carta_md) { return [{ json: { ok: false, info: 'sin vault_path o carta en BD' } }]; }
const folder = vp.slice(0, vp.lastIndexOf('/'));
const path = folder + '/Carta de presentacion.md';
const today = new Date().toISOString().slice(0, 10);
const FOOTER = '[Tu Nombre]  |  [tu-email]  |  [tu-web]  |  [tu-github]';
const carta = ['# Carta de presentacion', '', '**Para:** ' + (r.company || '') + '  |  **Puesto:** ' + (r.title || ''), '**Asunto:** ' + (r.asunto || ''), '**Fecha:** ' + today, '', '---', '', (r.carta_md || ''), '', '---', FOOTER].join(NL);
try { fs.mkdirSync(folder, { recursive: true }); fs.writeFileSync(path, Buffer.from(carta, 'utf8')); return [{ json: { ok: true, path: path } }]; }
catch (e) { return [{ json: { ok: false, error: String((e && e.message) || e) } }]; }
